# Independent validation tests for lollipop()
# Generated by /validate-function lollipop depth=exhaustive (2026-11-19).
# Live tests lock in verified behavior; skip-guarded tests encode confirmed open defects.

lol_val_row <- function(res, key) {
  df <- res$summary$asDF
  m <- df[gsub('^"|"$', "", rownames(df)) == key, , drop = FALSE]
  expect_equal(nrow(m), 1L)
  m
}

lol_val_num <- function(res, key) {
  suppressWarnings(as.numeric(trimws(as.character(lol_val_row(res, key)$value))))
}

lol_val_capture_plot <- function(res) {
  tmp <- tempfile(fileext = ".png")
  on.exit(unlink(tmp), add = TRUE)
  res$plot$saveAs(tmp)
  ggplot2::last_plot()
}

# --- LIVE TESTS (PASSING CLAIMS) ---

test_that("C01-C10: known-answer hand arithmetic under mean, sum, median, and none", {
  # Oracle: exact hand arithmetic on tiny n = 10 dataset with tie and NA
  d <- data.frame(
    val = c(10, 20, 30, 10, 10, NA, 20, 40, 60, 40),
    grp = factor(
      c("Beta", "Beta", "Beta", "Alpha", "Alpha", "Alpha",
        "Gamma", "Gamma", "Gamma", "Delta"),
      levels = c("Beta", "Alpha", "Gamma", "Delta")
    )
  )

  # Mean aggregation: Beta=20, Alpha=10, Gamma=40, Delta=40 -> mean=27.5, med=30, sd=15
  r_mean <- suppressWarnings(ClinicoPath::lollipop(
    data = d, dep = "val", group = "grp", highlight = NULL, aggregation = "mean"
  ))
  expect_equal(lol_val_row(r_mean, "n_obs")$statistic, "Number of Plotted Points")
  expect_equal(lol_val_num(r_mean, "n_obs"), 4)
  expect_equal(lol_val_num(r_mean, "n_groups"), 4)
  expect_equal(lol_val_num(r_mean, "mean"), 27.5)
  expect_equal(lol_val_num(r_mean, "median"), 30)
  expect_equal(lol_val_num(r_mean, "sd"), 15)
  expect_equal(lol_val_row(r_mean, "range")$value, "10 - 40")
  expect_equal(lol_val_row(r_mean, "highest")$value, "Gamma, Delta")
  expect_equal(lol_val_row(r_mean, "lowest")$value, "Alpha")
  expect_match(r_mean$summary$notes$aggregation$note,
               "4 plotted per-group mean values aggregated from 9 observations", fixed = TRUE)

  # Sum aggregation: Beta=60, Alpha=20, Gamma=120, Delta=40 -> mean=60, med=50, sd=sqrt(5600/3)
  r_sum <- suppressWarnings(ClinicoPath::lollipop(
    data = d, dep = "val", group = "grp", highlight = NULL, aggregation = "sum"
  ))
  st_sum <- r_sum$plot$state$data
  expect_equal(
    st_sum$dependent[match(c("Beta", "Alpha", "Gamma", "Delta"), as.character(st_sum$group))],
    c(60, 20, 120, 40), tolerance = 1e-12
  )
  expect_equal(sd(st_sum$dependent), sqrt(5600 / 3), tolerance = 1e-12)
  expect_equal(lol_val_row(r_sum, "highest")$value, "Gamma")

  # Median aggregation: A=2, B=20, C=5 -> mean=9, med=5, sd=sqrt(93)
  d_med <- data.frame(
    val = c(1, 2, 100, 10, 20, 30, 5, 5, 5),
    grp = factor(c("A", "A", "A", "B", "B", "B", "C", "C", "C"), levels = c("A", "B", "C"))
  )
  r_med <- suppressWarnings(ClinicoPath::lollipop(
    data = d_med, dep = "val", group = "grp", highlight = NULL, aggregation = "median"
  ))
  expect_equal(r_med$plot$state$data$dependent, c(2, 20, 5), tolerance = 1e-12)
  expect_equal(sd(r_med$plot$state$data$dependent), sqrt(93), tolerance = 1e-12)

  # None aggregation: 9 complete rows, mean=240/9, med=20, sd=sqrt(300)
  r_none <- suppressWarnings(ClinicoPath::lollipop(
    data = d, dep = "val", group = "grp", highlight = NULL, aggregation = "none"
  ))
  expect_equal(lol_val_row(r_none, "n_obs")$statistic, "Number of Observations")
  expect_equal(lol_val_num(r_none, "n_obs"), 9)
  expect_equal(mean(r_none$plot$state$data$dependent), 240 / 9, tolerance = 1e-12)
  expect_equal(sd(r_none$plot$state$data$dependent), sqrt(300), tolerance = 1e-12)
  expect_equal(lol_val_row(r_none, "lowest")$value, "Beta, Alpha")
  expect_null(r_none$summary$notes[["aggregation"]])
})

test_that("C10: reference parity on bundled clinical_lab_data and lollipop_biomarkers", {
  # Oracle: independent base-R tapply on complete cases of bundled datasets
  clab <- ClinicoPath::clinical_lab_data
  clab_cc <- clab[complete.cases(clab[, c("hemoglobin", "treatment_group")]), ]
  ref_hb <- tapply(clab_cc$hemoglobin, clab_cc$treatment_group, mean)
  res_clab <- suppressWarnings(ClinicoPath::lollipop(
    data = clab, dep = "hemoglobin", group = "treatment_group",
    highlight = NULL, aggregation = "mean"
  ))
  obs_hb <- setNames(res_clab$plot$state$data$dependent,
                     as.character(res_clab$plot$state$data$group))[names(ref_hb)]
  expect_equal(unname(obs_hb), as.numeric(ref_hb), tolerance = 1e-12)

  lbio <- ClinicoPath::lollipop_biomarkers
  lbio_cc <- lbio[complete.cases(lbio[, c("cea", "cancer_type")]), ]
  ref_bio <- tapply(lbio_cc$cea, lbio_cc$cancer_type, median)
  res_bio <- suppressWarnings(ClinicoPath::lollipop(
    data = lbio, dep = "cea", group = "cancer_type",
    highlight = NULL, aggregation = "median"
  ))
  obs_bio <- setNames(res_bio$plot$state$data$dependent,
                      as.character(res_bio$plot$state$data$group))[names(ref_bio)]
  expect_equal(unname(obs_bio), as.numeric(ref_bio), tolerance = 1e-12)
})

test_that("C10-C11: metamorphic invariants (permutation, rename, scale, shift, duplicate, UTF-8)", {
  # Oracle: mathematical invariances of mean, sum, and SD
  set.seed(20260101)
  d <- data.frame(
    y = c(12, 18, 25, 35, 50, 70, 5, 15),
    g = factor(c("Ctrl", "Ctrl", "Low", "Low", "High", "High", "Placebo", "Placebo"),
               levels = c("Ctrl", "Low", "High", "Placebo"))
  )
  r0 <- suppressWarnings(ClinicoPath::lollipop(data = d, dep = "y", group = "g", highlight = NULL))
  rp <- suppressWarnings(ClinicoPath::lollipop(data = d[sample(nrow(d)), ], dep = "y", group = "g", highlight = NULL))
  expect_equal(rp$plot$state$data$dependent, r0$plot$state$data$dependent, tolerance = 1e-12)

  d_sc <- d; d_sc$y <- d_sc$y * 10
  r_sc <- suppressWarnings(ClinicoPath::lollipop(data = d_sc, dep = "y", group = "g", highlight = NULL))
  expect_equal(r_sc$plot$state$data$dependent, r0$plot$state$data$dependent * 10, tolerance = 1e-12)

  d_sh <- d; d_sh$y <- d_sh$y + 100
  r_sh <- suppressWarnings(ClinicoPath::lollipop(data = d_sh, dep = "y", group = "g", highlight = NULL))
  expect_equal(sd(r_sh$plot$state$data$dependent), sd(r0$plot$state$data$dependent), tolerance = 1e-12)

  d_dup <- rbind(d, d)
  r_dm <- suppressWarnings(ClinicoPath::lollipop(data = d_dup, dep = "y", group = "g", highlight = NULL, aggregation = "mean"))
  r_ds <- suppressWarnings(ClinicoPath::lollipop(data = d_dup, dep = "y", group = "g", highlight = NULL, aggregation = "sum"))
  r_0s <- suppressWarnings(ClinicoPath::lollipop(data = d, dep = "y", group = "g", highlight = NULL, aggregation = "sum"))
  expect_equal(r_dm$plot$state$data$dependent, r0$plot$state$data$dependent, tolerance = 1e-12)
  expect_equal(r_ds$plot$state$data$dependent, r_0s$plot$state$data$dependent * 2, tolerance = 1e-12)

  # jamovi values-attributed Nominal integer column
  f_val <- factor(c("10", "20", "30", "40"))
  attr(f_val, "values") <- c(10L, 20L, 30L, 40L)
  d_jmv <- data.frame(y = f_val, g = factor(c("A", "A", "B", "B")))
  r_jmv <- suppressWarnings(ClinicoPath::lollipop(data = d_jmv, dep = "y", group = "g", highlight = NULL))
  expect_equal(r_jmv$plot$state$data$dependent, c(15, 35), tolerance = 1e-12)
})

test_that("C13-C19: plot layer coordinates, showMean, conditionalColor, highlight, and redraw", {
  # Oracle: ggplot2::ggplot_build() layer inspection against input data & options
  d <- data.frame(y = c(10, 20, 30), g = factor(c("Lo", "Eq", "Hi"), levels = c("Lo", "Eq", "Hi")))
  r_cc <- suppressWarnings(ClinicoPath::lollipop(
    data = d, dep = "y", group = "g", highlight = "Lo",
    useHighlight = TRUE, conditionalColor = TRUE, colorThreshold = 20,
    baseline = 5, showMean = TRUE
  ))
  expect_match(r_cc$notices$content, "Highlighting Ignored", fixed = TRUE)
  gb <- ggplot2::ggplot_build(lol_val_capture_plot(r_cc))
  expect_equal(unique(gb$data[[1]]$y), 5)
  expect_equal(gb$data[[1]]$yend, c(10, 20, 30))
  expect_equal(gb$data[[2]]$colour, c("#56B4E9", "#56B4E9", "#E69F00"))
  expect_equal(gb$data[[3]]$yintercept, 20)

  # Jamovi redraw with private$.data <- NULL
  opts <- ClinicoPath:::lollipopOptions$new(dep = "y", group = "g", highlight = NULL)
  an <- ClinicoPath:::lollipopClass$new(options = opts, data = d)
  an$run()
  st <- an$results$plot$state
  an2 <- ClinicoPath:::lollipopClass$new(options = opts, data = d)
  an2$init()
  an2$.__enclos_env__$private$.data <- NULL
  an2$results$plot$setState(st)
  tmp <- tempfile(fileext = ".png")
  on.exit(unlink(tmp), add = TRUE)
  grDevices::png(tmp)
  ok <- an2$.__enclos_env__$private$.plot(an2$results$plot, NULL, NULL)
  grDevices::dev.off()
  expect_true(isTRUE(ok))
})

test_that("C21-C28: guard thresholds fire at exact boundaries", {
  # Oracle: documented threshold rules in R/lollipop.b.R
  # Small sample (< 10)
  d9  <- data.frame(y = 1:9,  g = factor(rep(c("A", "B", "C"), each = 3)))
  d10 <- data.frame(y = 1:10, g = factor(c(rep("A", 4), rep("B", 3), rep("C", 3))))
  expect_match(ClinicoPath::lollipop(data = d9, dep = "y", group = "g", highlight = NULL)$notices$content,
               "Small Sample Size", fixed = TRUE)
  expect_false(grepl("Small Sample Size",
                     ClinicoPath::lollipop(data = d10, dep = "y", group = "g", highlight = NULL)$notices$content,
                     fixed = TRUE))

  # Tukey 3*IQR far-out boundary (Q1=12, Q3=16, IQR=4 -> Q3+3*IQR=28)
  d_eq <- data.frame(y = c(10:17, 28.0), g = factor(paste0("G", 1:9)))
  d_hi <- data.frame(y = c(10:17, 28.1), g = factor(paste0("G", 1:9)))
  expect_false(grepl("Extreme Values Present",
                     ClinicoPath::lollipop(data = d_eq, dep = "y", group = "g", highlight = NULL)$notices$content,
                     fixed = TRUE))
  expect_match(ClinicoPath::lollipop(data = d_hi, dep = "y", group = "g", highlight = NULL)$notices$content,
               "Extreme Values Present", fixed = TRUE)

  # Baseline far from data (< 0.25)
  d_bf_lo <- data.frame(y = c(76, 100), g = factor(c("A", "B")))
  d_bf_eq <- data.frame(y = c(75, 100), g = factor(c("A", "B")))
  expect_match(ClinicoPath::lollipop(data = d_bf_lo, dep = "y", group = "g", highlight = NULL, baseline = 0)$notices$content,
               "Baseline Far From the Data", fixed = TRUE)
  expect_false(grepl("Baseline Far From the Data",
                     ClinicoPath::lollipop(data = d_bf_eq, dep = "y", group = "g", highlight = NULL, baseline = 0)$notices$content,
                     fixed = TRUE))
})

# --- REGRESSION TESTS FOR REPAIRED VALIDATION DEFECTS ---

test_that("C30: asSource() emits highlight = NULL when unset so syntax executes cleanly", {
  d <- data.frame(y = c(10, 20, 30, 40), g = factor(c("A", "A", "B", "B")))
  opts <- ClinicoPath:::lollipopOptions$new(dep = "y", group = "g", highlight = NULL, sortBy = "value_desc")
  an <- ClinicoPath:::lollipopClass$new(options = opts, data = d)
  an$run()
  src <- an$asSource()
  expect_match(src, "highlight\\s*=\\s*NULL")
  data <- d
  res <- eval(parse(text = src))
  expect_equal(res$summary$asDF$value, an$results$summary$asDF$value)
})

test_that("C25: 2-group extreme imbalance triggers Unbalanced and Mean Line warnings", {
  d <- data.frame(y = c(rep(10, 100), rep(50, 2)), g = factor(c(rep("A", 100), rep("B", 2))))
  res <- ClinicoPath::lollipop(data = d, dep = "y", group = "g", highlight = NULL, showMean = TRUE)
  expect_match(res$notices$content, "Unbalanced Group Sizes", fixed = TRUE)
  expect_match(res$notices$content, "Mean Line Averages the Group Summaries", fixed = TRUE)
})

test_that("C07/C15: floating-point derived sum(0.1, 0.2) matches 0.3 for ties and colorThreshold", {
  d <- data.frame(y = c(0.1, 0.2, 0.3), g = factor(c("A", "A", "B"), levels = c("A", "B")))
  res <- ClinicoPath::lollipop(data = d, dep = "y", group = "g", highlight = NULL,
                               aggregation = "sum", conditionalColor = TRUE, colorThreshold = 0.3)
  expect_equal(lol_val_row(res, "highest")$value, "A, B")
  gb <- ggplot2::ggplot_build(lol_val_capture_plot(res))
  expect_true(all(gb$data[[2]]$colour == "#56B4E9"))
})

# Updated 2026-11-26: lollipop now lets jmvcore::reject() propagate instead of swallowing errors into todo HTML or hiding outputs on failure (guide §5, §16).
test_that("C11: explicit NA factor level via addNA() is treated as missing, not a real group", {
  d <- data.frame(y = c(10, 20, 30, 40), g = addNA(factor(c("A", "A", NA, NA))))
  expect_error(
    ClinicoPath::lollipop(data = d, dep = "y", group = "g", highlight = NULL),
    "at least 2"
  )
})

