test_that("UX: sign-aware vjust/hjust keeps diverging value labels off stems", {
  d <- data.frame(y = c(-5, 5), g = factor(c("Neg", "Pos"), levels = c("Neg", "Pos")))
  rv <- ClinicoPath::lollipop(data = d, dep = "y", group = "g", highlight = NULL,
                              baseline = 0, showValues = TRUE, orientation = "vertical")
  gbv <- ggplot2::ggplot_build(lol_val_capture_plot(rv))
  expect_equal(gbv$data[[3]]$vjust, c(1.5, -0.5))

  rh <- ClinicoPath::lollipop(data = d, dep = "y", group = "g", highlight = NULL,
                              baseline = 0, showValues = TRUE, orientation = "horizontal")
  gbh <- ggplot2::ggplot_build(lol_val_capture_plot(rh))
  expect_equal(gbh$data[[3]]$hjust, c(1.2, -0.2))
})
